// dev stages default to the docker-compose database; every other stage must set DATABASE_URL
const databaseUrlConfig = Config.Redacted("DATABASE_URL")
const databaseUrl = new URL(
  Redacted.value(
    yield* (yield* Alchemy.Stack).stage.startsWith("dev")
      ? databaseUrlConfig.pipe(
          Config.withDefault(Redacted.make("postgres://postgres:postgres@localhost:5432/app")),
        )
      : databaseUrlConfig,
  ),
)
const hyperdrive = yield* Cloudflare.Hyperdrive.Connection("Hyperdrive", {
  origin: {
    scheme: "postgres",
    host: databaseUrl.hostname,
    port: Number(databaseUrl.port || 5432),
    database: databaseUrl.pathname.slice(1),
    user: decodeURIComponent(databaseUrl.username),
    password: Redacted.make(decodeURIComponent(databaseUrl.password)),
  },
  // writes must be visible to the next read, so only pool connections, don't cache queries
  caching: { disabled: true },
})
